// src/pages/ManageUserAccounts.jsx

import React, { useState, useEffect } from "react";
import "./manageUserAccounts.css";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";

function ManageUserAccounts() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [password, setPassword] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  const [editingIndex, setEditingIndex] = useState(null);
  const [editingType, setEditingType] = useState("");
  const [editingId, setEditingId] = useState(null);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    const [studentRes, supervisorRes, evaluatorRes] = await Promise.all([
      fetch("http://localhost:5000/api/student"),
      fetch("http://localhost:5000/api/admin"),
      fetch("http://localhost:5000/api/evaluator"),
    ]);

    const studentsData = await studentRes.json();
    const supervisorsData = await supervisorRes.json();
    const evaluatorsData = await evaluatorRes.json();

    setStudents(studentsData);
    setSupervisors(supervisorsData);
    setEvaluators(evaluatorsData);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingId) {
        // Just update name and email if needed here
        alert("Update logic not implemented yet.");
        return;
      }

      // 1. Create User
      const userRes = await fetch("http://localhost:5000/api/user", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: name, email, password, role }),
      });

      const user = await userRes.json();
      if (!user._id) throw new Error("User creation failed");

      // 2. Create Role-specific document
      let route = "";
      let roleBody = {};
      if (role === "Student") {
        route = "student";
        roleBody = {
          userId: user._id,
          studentName: name,
          regNo: registrationNumber,
          isGrouped: false,
        };
      } else if (role === "Supervisor") {
        route = "admin";
        roleBody = { userId: user._id, name };
      } else if (role === "Evaluator") {
        route = "evaluator";
        roleBody = { userId: user._id, name };
      }

      await fetch(`http://localhost:5000/api/${route}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(roleBody),
      });

      await fetchUsers();
      resetForm();
      alert("User added successfully.");
    } catch (err) {
      console.error(err);
      alert("Error creating user.");
    }
  };

  const handleResetPassword = async (userId) => {
    const newPassword = prompt("Enter new password:");
    if (!newPassword) return;

    try {
      await fetch(`http://localhost:5000/api/user/reset-password/${userId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password: newPassword }),
      });
      alert("Password reset successfully.");
    } catch (err) {
      console.error(err);
      alert("Failed to reset password.");
    }
  };

  const handleDelete = async (userId, docId, type) => {
    try {
      // Delete User
      await fetch(`http://localhost:5000/api/user/${userId}`, {
        method: "DELETE",
      });

      // Delete Role-specific document
      const subRoute =
        type === "student"
          ? "student"
          : type === "supervisor"
          ? "admin"
          : "evaluator";

      await fetch(`http://localhost:5000/api/${subRoute}/${docId}`, {
        method: "DELETE",
      });

      await fetchUsers();
      alert("User deleted successfully.");
    } catch (err) {
      console.error(err);
      alert("Error deleting user.");
    }
  };

  const resetForm = () => {
    setName("");
    setEmail("");
    setRole("");
    setPassword("");
    setRegistrationNumber("");
    setEditingIndex(null);
    setEditingType("");
    setEditingId(null);
  };

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>Manage User Accounts</h1>
          <form onSubmit={handleSubmit} className="user-form">
            <label>Name</label>
            <input
              type="text"
              value={name}
              required
              onChange={(e) => setName(e.target.value)}
            />

            <label>Email</label>
            <input
              type="email"
              value={email}
              required
              onChange={(e) => setEmail(e.target.value)}
            />

            <label>Password</label>
            <input
              type="password"
              value={password}
              required={!editingId}
              onChange={(e) => setPassword(e.target.value)}
            />

            <label>Role</label>
            <select
              value={role}
              required
              onChange={(e) => setRole(e.target.value)}
            >
              <option value="">Select Role</option>
              <option value="Student">Student</option>
              <option value="Supervisor">Supervisor</option>
              <option value="Evaluator">Evaluator</option>
            </select>

            {role === "Student" && (
              <>
                <label>Registration Number</label>
                <input
                  type="text"
                  value={registrationNumber}
                  required
                  onChange={(e) => setRegistrationNumber(e.target.value)}
                />
              </>
            )}

            {role === "Evaluator" && (
              <>
                <label>Registration Number</label>
                <input
                  type="text"
                  disabled
                  placeholder="Not applicable"
                />
              </>
            )}

            <button type="submit">
              {editingId ? "Update User" : "Create User"}
            </button>
          </form>

          {/* STUDENT LIST */}
          <h2>Students</h2>
          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Reg No</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {students.map((s, i) => (
                <tr key={i}>
                  <td>{s.studentName}</td>
                  <td>{s.regNo}</td>
                  <td>
                    <button onClick={() => handleResetPassword(s.userId)}>
                      Reset Password
                    </button>
                    <button onClick={() => handleDelete(s.userId, s._id, "student")}>
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* SUPERVISOR LIST */}
          <h2>Supervisors</h2>
          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {supervisors.map((s, i) => (
                <tr key={i}>
                  <td>{s.name}</td>
                  <td>
                    <button onClick={() => handleResetPassword(s.userId)}>
                      Reset Password
                    </button>
                    <button onClick={() => handleDelete(s.userId, s._id, "supervisor")}>
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* EVALUATOR LIST */}
          <h2>Evaluators</h2>
          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {evaluators.map((e, i) => (
                <tr key={i}>
                  <td>{e.name}</td>
                  <td>
                    <button onClick={() => handleResetPassword(e.userId)}>
                      Reset Password
                    </button>
                    <button onClick={() => handleDelete(e.userId, e._id, "evaluator")}>
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default ManageUserAccounts;
